import{_ as a,o as n,c as r,j as e,a as d}from"./chunks/framework.QQy01QNh.js";const m=JSON.parse('{"title":"D.22　阶级、身份、不平等与社会排斥","description":"","frontmatter":{"title":"D.22　阶级、身份、不平等与社会排斥"},"headers":[],"relativePath":"theory/appendix-d/d-22.md","filePath":"theory/appendix-d/d-22.md"}'),l={name:"theory/appendix-d/d-22.md"};function o(s,t,p,i,c,u){return n(),r("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-22",tabindex:"-1"},[d("D.22　阶级、身份、不平等与社会排斥 "),e("a",{class:"header-anchor",href:"#section-d-22","aria-label":'Permalink to "D.22　阶级、身份、不平等与社会排斥 {#section-d-22}"'},"​")]),e("p",null,"正文连接：§2.5；§5.5.1；§9.7；§10.5—10.8；§14.4—14.5。研究入口：22.01—22.08。"),e("p",null,"收入、财富、现金缓冲、生产与管理控制、资格、社会关系和承认地位是不同资源。阶级与阶层研究、污名和社会边界、交叉性、精英再生产、殖民与劳动、贫困和流动各自指出可能的通道，不能由一项身份类别直接诊断某个人处境。"),e("p",null,"命名不证明已有共同意志，但命名可以经分类、服务资格、就业和互动产生真实作用。交叉性不仅是圈层重叠或身份数目，更要问几套规则怎样共同排除某一位置；统计交互、制度交叉与生活经验又须分别论证。一个群体平均改善与内部仍有排斥可以同时成立。"),e("p",null,"教育和社会流动须区分出生队列、报名、录取、毕业及后续机会。测到技能差异并不证明教学机会公平，观察到少数成功也不能代表全部制度开放。反过来，存在选择障碍不取消真实技能的价值。精英控制要追踪准入、议程、资源和撤换机制，不能仅凭学历或职业命名。"),e("p",null,"教学例：某项福利提高地区平均收入，但没有证件的人未被纳入统计和申请。平均结果可以保持真实，覆盖主张必须收窄并单列未进入者。贫困带来的时间、交通、照护与取证成本应作为具体约束，不转化成能力或品格定论；承认、再分配和参与权各有需要回答的问题。"),e("p",null,"资源成为个人机会需要时间、用途、控制与执行条件。家庭总量、企业资产或群体均值可以回答总量问题，却不能直接给个人配置控制权和福利。身份标签的效应须经实际到达雇主、服务规则或互动过程的通道；研究者内部标签不自动激活这些后果。相对差距缩小与绝对差距扩大也可同时成立，须分别说明比较目标。"),e("p",null,"专题定位：22.01 阶级、阶层与资本分布；22.02 地位、污名与社会边界；22.03 性别、种族、族群与交叉性；22.04 精英、寡头与权力再生产；22.05 殖民、奴隶制与种族化劳动；22.06 贫困、剥夺与稀缺；22.07 社会流动、教育与继承；22.08 承认、再分配与共同生活。")],-1)])])}const f=a(l,[["render",o]]);export{m as __pageData,f as default};
